"""
URL Fetcher Service - A microservice for fetching URLs on behalf of clients.

This service provides a REST API for fetching content from URLs,
with SSRF protection based on hostname and resolved-address validation.
"""

import ipaddress
import socket
from urllib.parse import urljoin, urlparse

from flask import Flask, request, jsonify
import requests
from requests.exceptions import RequestException

from config import (
    HOST,
    PORT,
    DEBUG,
    REQUEST_TIMEOUT,
    MAX_REDIRECTS,
    MAX_RESPONSE_SIZE,
    BLOCKED_HOSTNAMES,
    ALLOWED_PROTOCOLS,
    RATE_LIMIT_PER_MINUTE,
)


app = Flask(__name__)


def _normalize_hostname(hostname):
    """Return a lower-case hostname without a single trailing DNS dot."""
    if not hostname:
        return None
    hostname = hostname.strip().lower()
    if hostname.endswith('.'):
        hostname = hostname[:-1]
    return hostname


def _canonicalize_ip(host):
    """
    Return a canonical IP string for an IP literal, including legacy IPv4
    formats such as 127.1, 2130706433, 0x7f000001, and 0177.0.0.1.
    """
    try:
        return str(ipaddress.ip_address(host))
    except ValueError:
        pass

    try:
        return socket.inet_ntoa(socket.inet_aton(host))
    except (OSError, ValueError, UnicodeError):
        return None


def _is_public_ip(ip_string):
    """Return True only when an IP address is a public, globally routable IP."""
    if not ip_string:
        return False

    # Scoped IPv6 addresses include a zone id (for example fe80::1%eth0).
    address = ip_string.split('%', 1)[0]

    try:
        parsed = ipaddress.ip_address(address)
    except ValueError:
        return False

    # Check IPv4-mapped IPv6 addresses against the underlying IPv4 address
    # so that ::ffff:127.0.0.1 is treated as loopback.
    if isinstance(parsed, ipaddress.IPv6Address) and parsed.ipv4_mapped is not None:
        parsed = parsed.ipv4_mapped

    return parsed.is_global


def _resolve_host(host):
    """
    Validate a hostname or IP literal.

    Returns:
        tuple: (is_safe: bool, error_message: str or None)
    """
    if not host:
        return False, "URL must include a hostname"

    if host in BLOCKED_HOSTNAMES:
        return False, f"Access to '{host}' is blocked for security reasons"

    literal_ip = _canonicalize_ip(host)
    if literal_ip is not None:
        if _is_public_ip(literal_ip):
            return True, None
        return False, f"Access to internal address '{host}' is blocked"

    try:
        address_info = socket.getaddrinfo(
            host,
            None,
            type=socket.SOCK_STREAM,
        )
    except socket.gaierror:
        return False, f"Could not resolve hostname '{host}'"

    if not address_info:
        return False, f"Could not resolve hostname '{host}'"

    seen = set()
    for item in address_info:
        ip_address = item[4][0]
        if ip_address in seen:
            continue
        seen.add(ip_address)

        if not _is_public_ip(ip_address):
            return False, (
                f"Access to '{host}' is blocked because it resolves to "
                f"an internal address"
            )

    return True, None


def validate_url(url):
    """
    Validate a URL for SSRF protection.

    Uses URL parsing, hostname normalization, IP literal canonicalization,
    and DNS resolution checks to reject requests to internal resources.

    Args:
        url: The URL string to validate

    Returns:
        tuple: (is_valid: bool, parsed_url: ParseResult or None, error_message: str or None)
    """
    if not isinstance(url, str) or not url:
        return False, None, "URL is required"

    try:
        parsed = urlparse(url)
        # Accessing .port validates malformed and out-of-range ports.
        _ = parsed.port
        hostname = parsed.hostname
    except ValueError as exc:
        return False, None, f"Invalid URL format: {str(exc)}"
    except Exception as exc:
        return False, None, f"Invalid URL format: {str(exc)}"

    # Check protocol
    if parsed.scheme.lower() not in ALLOWED_PROTOCOLS:
        return (
            False,
            parsed,
            f"Protocol '{parsed.scheme}' not allowed. Use: {', '.join(ALLOWED_PROTOCOLS)}",
        )

    # Embedded credentials are not needed by this service and are a common
    # source of parser-differential SSRF bypasses.
    if parsed.username is not None or parsed.password is not None:
        return False, parsed, "URLs containing embedded credentials are not allowed"

    if not parsed.netloc:
        return False, parsed, "URL must include a hostname"

    # Reject control characters and whitespace in the authority component.
    if any(char.isspace() or ord(char) < 32 for char in parsed.netloc):
        return False, parsed, "URL authority contains invalid characters"

    # Backslashes are handled inconsistently by some URL parsers and are not
    # valid in normal HTTP URLs.
    if '\\' in parsed.netloc:
        return False, parsed, "URL authority contains invalid characters"

    normalized_host = _normalize_hostname(hostname)

    if not normalized_host:
        return False, parsed, "URL must include a valid hostname"

    # A percent sign is not valid in a hostname/IP literal. Rejecting it
    # prevents encoded-host parser differentials.
    if '%' in normalized_host:
        return False, parsed, "URL hostname contains invalid characters"

    is_safe, error = _resolve_host(normalized_host)
    if not is_safe:
        return False, parsed, error

    return True, parsed, None


def fetch_url(url):
    """
    Fetch content from a URL.

    Redirects are followed manually so that every redirect destination is
    validated by validate_url before a request is made.

    Args:
        url: The URL to fetch

    Returns:
        dict: Response data including status, headers, and content
    """
    current_url = url
    response = None

    try:
        for redirect_count in range(MAX_REDIRECTS + 1):
            # Validate the original URL and every redirect target before
            # making the corresponding network request.
            is_valid, parsed, error = validate_url(current_url)

            if not is_valid:
                return {
                    "success": False,
                    "error": error,
                    "url": url,
                }

            response = requests.get(
                current_url,
                timeout=REQUEST_TIMEOUT,
                allow_redirects=False,
                stream=True,
            )

            if not response.is_redirect:
                break

            if redirect_count >= MAX_REDIRECTS:
                response.close()
                return {
                    "success": False,
                    "error": f"Too many redirects (max {MAX_REDIRECTS})",
                    "url": url,
                }

            location = response.headers.get('location')
            if not location:
                break

            next_url = urljoin(current_url, location)

            # Close the redirect response before continuing.
            response.close()
            current_url = next_url

        if response is None:
            return {
                "success": False,
                "error": "Request failed: no response received",
                "url": url,
            }

        # Check response size
        content_length = response.headers.get('content-length')
        if content_length:
            try:
                declared_length = int(content_length)
            except (TypeError, ValueError):
                declared_length = None

            if declared_length is not None and declared_length > MAX_RESPONSE_SIZE:
                response.close()
                return {
                    "success": False,
                    "error": f"Response too large (max {MAX_RESPONSE_SIZE} bytes)",
                    "url": url,
                }

        # Read content with size limit
        chunks = []
        total_length = 0
        for chunk in response.iter_content(chunk_size=8192):
            if not chunk:
                continue

            chunks.append(chunk)
            total_length += len(chunk)

            if total_length > MAX_RESPONSE_SIZE:
                response.close()
                return {
                    "success": False,
                    "error": f"Response too large (max {MAX_RESPONSE_SIZE} bytes)",
                    "url": url,
                }

        content = b"".join(chunks)

        # Try to decode as text
        try:
            text_content = content.decode('utf-8')
        except UnicodeDecodeError:
            text_content = None

        result = {
            "success": True,
            "status_code": response.status_code,
            "headers": dict(response.headers),
            "content": text_content,
            "content_length": len(content),
            "final_url": response.url,
            "url": url,
        }

        response.close()
        return result

    except requests.Timeout:
        return {
            "success": False,
            "error": f"Request timed out after {REQUEST_TIMEOUT} seconds",
            "url": url,
        }
    except requests.TooManyRedirects:
        return {
            "success": False,
            "error": f"Too many redirects (max {MAX_REDIRECTS})",
            "url": url,
        }
    except RequestException as exc:
        return {
            "success": False,
            "error": f"Request failed: {str(exc)}",
            "url": url,
        }


